using System.Buffers;

ArrayPool<byte> pool = ArrayPool<byte>.Shared;
byte[] buffer = null;

try
{
    // Rent a buffer — minimum 4096 bytes
    buffer = pool.Rent(4096);
    int bytesWritten = await FillBufferAsync(buffer);

    // Use only the written portion
    Span<byte> data = buffer.AsSpan(0, bytesWritten);
    await ProcessAsync(data);
}
finally
{
    // Always return the buffer to the pool
    if (buffer != null)
        pool.Return(buffer, clearArray: true);
}

