// Create a pool with custom limits for large buffers
ArrayPool<byte> largeBufferPool = ArrayPool<byte>.Create(
    maxArrayLength: 50 * 1024 * 1024, // 50 MB max per buffer
    maxArraysPerBucket: 50);           // retain up to 50 buffers per size

byte[] buffer = largeBufferPool.Rent(10 * 1024 * 1024); // 10 MB
try
{
    // Process the large buffer
}
finally
{
    largeBufferPool.Return(buffer);
